#!/usr/bin/env bash
set -euo pipefail
umask 077

# Generated by the qualified Actions run. No token, certificate or device key
# belongs in this file. Authenticate Docker on the VPS once before running it.
test "$(id -u)" = 0 || { echo 'Run in the VPS administrator console.'; exit 1; }
command -v docker >/dev/null
docker compose version >/dev/null
image='@@IMAGE_REF@@'
if ! docker pull "$image"; then
  echo 'Private GHCR pull failed. Check the network and log in once, then rerun:' >&2
  echo 'docker login ghcr.io -u kittawat-thongpud' >&2
  echo 'At Password, enter a GitHub personal access token (classic) with read:packages.' >&2
  echo 'Do not paste the token into chat or put it in a shell command.' >&2
  exit 1
fi

target=/opt/personal-vpn-p2p-lab
test ! -L "$target" || { echo 'Refusing a symlink installation directory.'; exit 1; }
install -d -m 750 "$target"
cd "$target"
test "$(pwd -P)" = "$target"
test ! -L signal-state || { echo 'Refusing a symlink state directory.'; exit 1; }
test ! -L compose.signal.yaml || { echo 'Refusing a symlink Compose file.'; exit 1; }
install -d -m 750 -o 10001 -g 10001 signal-state

# Never rotate an existing controller identity or erase its device database.
if test -e signal-state/server.key; then
  for file in server.key server.crt endpoint.txt devices.sqlite; do
    test -s "signal-state/$file" || { echo "Incomplete controller state: $file. State was kept; investigate before retrying."; exit 1; }
  done
elif test -n "$(find signal-state -mindepth 1 -maxdepth 1 -print -quit)"; then
  echo 'Partial controller state found. State was kept; investigate before retrying.'; exit 1
fi

cat > compose.signal.yaml.new <<'P2P_COMPOSE'
@@COMPOSE@@
P2P_COMPOSE
docker compose -f compose.signal.yaml.new config -q
mv -f compose.signal.yaml.new compose.signal.yaml
if ! test -f signal-state/server.key; then
  docker compose -f compose.signal.yaml run --rm --no-deps --interactive=false signal init --endpoint https://45.77.179.227:9443 >/dev/null
fi
docker compose -f compose.signal.yaml up -d --no-build --pull never --wait --wait-timeout 90
docker compose -f compose.signal.yaml ps
echo 'Private owner enrollment follows (one use, 10 minutes). Paste only into Windows P2P Lab; do not post in chat.'
docker compose -f compose.signal.yaml exec -T --interactive=false signal python /app/server.py owner-invite
echo 'Allow inbound TCP 9443 in the attached Vultr firewall and any enabled host firewall.'
echo 'To get a fresh invitation: cd /opt/personal-vpn-p2p-lab && docker compose -f compose.signal.yaml exec signal python /app/server.py owner-invite'
echo 'To stop this sidecar only: cd /opt/personal-vpn-p2p-lab && docker compose -f compose.signal.yaml down'
